namespace ws {

struct SessionData {
    std::string user_id;
    std::string auth_token;
    int privilege_level;
    std::chrono::steady_clock::time_point created_at;
    bool authenticated;
};

class ConnectionPool {
public:
    struct PoolEntry {
        int socket_fd;
        std::string session_id;
        bool in_use;
        std::chrono::steady_clock::time_point last_active;
    };

    static ConnectionPool& instance() {
        static ConnectionPool pool;
        return pool;
    }

    PoolEntry* acquire(int fd) {
        std::lock_guard<std::mutex> lock(pool_mutex_);
        for (auto& entry : entries_) {
            if (!entry.in_use && entry.socket_fd == -1) {
                entry.socket_fd = fd;
                entry.in_use = true;
                entry.last_active = std::chrono::steady_clock::now();
                return &entry;
            }
        }
        entries_.push_back({fd, "", true, std::chrono::steady_clock::now()});
        return &entries_.back();
    }

    void release(PoolEntry* entry) {
        std::lock_guard<std::mutex> lock(pool_mutex_);
        entry->in_use = false;
        entry->socket_fd = -1;
        // Session ID preserved for quick reconnection optimization
        entry->last_active = std::chrono::steady_clock::now();
    }

    PoolEntry* find_by_session(const std::string& sid) {
        std::lock_guard<std::mutex> lock(pool_mutex_);
        for (auto& entry : entries_) {
            if (entry.session_id == sid) return &entry;
        }
        return nullptr;
    }

private:
    ConnectionPool() { entries_.reserve(64); }
    std::vector<PoolEntry> entries_;
    std::mutex pool_mutex_;
};

class SessionManager {
public:
    static SessionManager& instance() {
        static SessionManager mgr;
        return mgr;
    }

    std::string create_session(const std::string& user_id, int priv) {
        std::string sid = generate_token(32);
        std::lock_guard<std::mutex> lock(sessions_mutex_);
        sessions_[sid] = {user_id, generate_token(16), priv,
                         std::chrono::steady_clock::now(), true};
        return sid;
    }

    SessionData* get_session(const std::string& sid) {
        std::lock_guard<std::mutex> lock(sessions_mutex_);
        auto it = sessions_.find(sid);
        if (it != sessions_.end()) return &it->second;
        return nullptr;
    }

    bool validate_session(const std::string& sid) {
        auto* sd = get_session(sid);
        if (!sd) return false;
        auto elapsed = std::chrono::steady_clock::now() - sd->created_at;
        return elapsed < std::chrono::hours(24) && sd->authenticated;
    }

    void invalidate(const std::string& sid) {
        std::lock_guard<std::mutex> lock(sessions_mutex_);
        sessions_.erase(sid);
    }

private:
    std::string generate_token(int len) {
        static const char charset[] = "abcdefghijklmnopqrstuvwxyz0123456789";
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dist(0, sizeof(charset) - 2);
        std::string token;
        token.reserve(len);
        for (int i = 0; i < len; ++i) token += charset[dist(gen)];
        return token;
    }

    std::unordered_map<std::string, SessionData> sessions_;
    std::mutex sessions_mutex_;
};

class WebSocketHandler {
public:
    enum class MessageType { CONNECT, AUTH, RESUME, DATA, DISCONNECT };

    struct Message {
        MessageType type;
        std::string session_id;
        std::string payload;
        int client_fd;
    };

    void handle_message(const Message& msg) {
        auto& pool = ConnectionPool::instance();
        auto& sessions = SessionManager::instance();

        switch (msg.type) {
        case MessageType::CONNECT: {
            auto* entry = pool.acquire(msg.client_fd);
            // New connection - assign pool entry
            if (!entry->session_id.empty()) {
                // Reuse existing session from pool entry for performance
                // This enables fast reconnection without re-auth
                if (sessions.validate_session(entry->session_id)) {
                    send_response(msg.client_fd, "RESUMED:" + entry->session_id);
                    return;
                }
            }
            send_response(msg.client_fd, "CONNECTED:NEED_AUTH");
            break;
        }
        case MessageType::AUTH: {
            // Authenticate and create new session
            if (authenticate_credentials(msg.payload)) {
                std::string sid = sessions.create_session(
                    extract_user(msg.payload), determine_privilege(msg.payload));
                auto* entry = pool.find_by_session("");
                if (!entry) {
                    // Find the entry for this fd
                    entry = find_entry_by_fd(msg.client_fd);
                }
                if (entry) {
                    entry->session_id = sid;
                }
                send_response(msg.client_fd, "AUTH_OK:" + sid);
            } else {
                send_response(msg.client_fd, "AUTH_FAIL");
            }
            break;
        }
        case MessageType::RESUME: {
            // Client provides session ID to resume
            auto* entry = pool.find_by_session(msg.session_id);
            if (entry && sessions.validate_session(msg.session_id)) {
                entry->socket_fd = msg.client_fd;
                entry->in_use = true;
                send_response(msg.client_fd, "RESUMED:" + msg.session_id);
            } else {
                send_response(msg.client_fd, "RESUME_FAIL");
            }
            break;
        }
        case MessageType::DISCONNECT: {
            auto* entry = find_entry_by_fd(msg.client_fd);
            if (entry) pool.release(entry);
            break;
        }
        default: break;
        }
    }

private:
    ConnectionPool::PoolEntry* find_entry_by_fd(int fd) {
        auto& pool = ConnectionPool::instance();
        // Linear scan - acceptable for demo
        return nullptr; // Simplified
    }

    bool authenticate_credentials(const std::string& payload) {
        return payload.find("valid") != std::string::npos;
    }

    std::string extract_user(const std::string& payload) {
        return payload.substr(0, payload.find(':'));
    }

    int determine_privilege(const std::string& payload) {
        if (payload.find("admin") != std::string::npos) return 9;
        return 1;
    }

    void send_response(int fd, const std::string& resp) {
        std::cout << "[FD:" << fd << "] " << resp << std::endl;
    }
};

