    handler.handle_message({ws::WebSocketHandler::MessageType::CONNECT, "", "", 10});
    handler.handle_message({ws::WebSocketHandler::MessageType::AUTH, "", "admin:valid", 10});

    // Admin disconnects
    handler.handle_message({ws::WebSocketHandler::MessageType::DISCONNECT, "", "", 10});

    // Attacker connects - gets same pool entry with admin's session
    handler.handle_message({ws::WebSocketHandler::MessageType::CONNECT, "", "", 20});

